node -e "
const fs=require('fs');
const h=fs.readFileSync('game.html','utf8');
let s=h.match(/<script>([\s\S]*?)<\/script>/)[1];
// stub out DOM-dependent tail
s=s.replace(/\/\* ---- GLOBAL CONTROLS ----[\s\S]*\$/,'');
s+='\nmodule.exports={newState,greedyTurn,runBenchmark,stateHash,serialize,deserialize,scoreOf,popCount,storageCap,RES,runTests};';
fs.writeFileSync('/tmp/g.js',s);
const m=require('/tmp/g.js');
let st=m.newState(1337);
for(let i=0;i<60;i++){st.over=null;m.greedyTurn(st);}
console.log('t60 pop',m.popCount(st),'res',JSON.stringify(st.res),'score',m.scoreOf(st).total);
const b1=m.runBenchmark(1337,200),b2=m.runBenchmark(1337,200);
console.log('bench',b1.hash,b2.hash,b1.hash===b2.hash,JSON.stringify(b1));
console.log('roundtrip',m.stateHash(st)===m.stateHash(m.deserialize(m.serialize(st))));
"
